-- Audience research: synthetic personas grounded in a project's brief, studies
-- that ask them the same questions, the reports those studies produce, and the
-- 1:1 conversations with a persona. Everything is generated by the user's own
-- LLM runtime and kept here; nothing leaves the machine except those LLM calls.

-- An audience is a brief (what the product is, who it is for) and the personas
-- generated from it. status: draft (brief only) -> building -> ready | failed.
-- generation counts regenerations: personas of an older generation are gone,
-- the studies that asked them keep their own copy of who answered.
CREATE TABLE IF NOT EXISTS audiences (
    id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    name            TEXT        NOT NULL CHECK (name <> ''),
    repository_id   UUID        REFERENCES repositories(id) ON DELETE SET NULL,
    status          TEXT        NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'building', 'ready', 'failed')),
    brief           JSONB       NOT NULL DEFAULT '{}',
    persona_target  INTEGER     NOT NULL DEFAULT 12 CHECK (persona_target BETWEEN 1 AND 40),
    product_context TEXT        NOT NULL DEFAULT '',
    generation      INTEGER     NOT NULL DEFAULT 0,
    error           TEXT        NOT NULL DEFAULT '',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    built_at        TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_audiences_repository ON audiences (repository_id);
CREATE INDEX IF NOT EXISTS idx_audiences_created ON audiences (created_at DESC);

CREATE TABLE IF NOT EXISTS audience_personas (
    id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    audience_id UUID        NOT NULL REFERENCES audiences(id) ON DELETE CASCADE,
    ordinal     INTEGER     NOT NULL,
    generation  INTEGER     NOT NULL DEFAULT 1,
    name        TEXT        NOT NULL CHECK (name <> ''),
    segment     TEXT        NOT NULL DEFAULT '',
    profile     JSONB       NOT NULL DEFAULT '{}',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_audience_personas_audience ON audience_personas (audience_id, ordinal);

-- A study asks every persona of an audience the same questions. status:
-- draft -> running -> synthesizing -> done | failed | cancelled. questions is
-- the extra open questions on top of the built-in purchase-intent core;
-- price_points are the prices every persona is asked to react to. report is
-- the synthesis, written once at the end.
CREATE TABLE IF NOT EXISTS audience_studies (
    id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    audience_id      UUID        NOT NULL REFERENCES audiences(id) ON DELETE CASCADE,
    title            TEXT        NOT NULL CHECK (title <> ''),
    goal             TEXT        NOT NULL DEFAULT '',
    questions        JSONB       NOT NULL DEFAULT '[]',
    price_points     JSONB       NOT NULL DEFAULT '[]',
    currency         TEXT        NOT NULL DEFAULT 'USD',
    product_snapshot TEXT        NOT NULL DEFAULT '',
    status           TEXT        NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'running', 'synthesizing', 'done', 'failed', 'cancelled')),
    persona_total    INTEGER     NOT NULL DEFAULT 0,
    persona_done     INTEGER     NOT NULL DEFAULT 0,
    persona_failed   INTEGER     NOT NULL DEFAULT 0,
    calls_estimate   INTEGER     NOT NULL DEFAULT 0,
    error            TEXT        NOT NULL DEFAULT '',
    report           JSONB,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at       TIMESTAMPTZ,
    finished_at      TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_audience_studies_audience ON audience_studies (audience_id, created_at DESC);

-- One row per persona that was asked. persona is a copy of who they were when
-- they answered, so a regenerated audience does not erase what the study found.
CREATE TABLE IF NOT EXISTS audience_study_answers (
    id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    study_id   UUID        NOT NULL REFERENCES audience_studies(id) ON DELETE CASCADE,
    persona_id UUID        REFERENCES audience_personas(id) ON DELETE SET NULL,
    persona    JSONB       NOT NULL DEFAULT '{}',
    status     TEXT        NOT NULL DEFAULT 'ok' CHECK (status IN ('ok', 'failed')),
    answers    JSONB       NOT NULL DEFAULT '{}',
    error      TEXT        NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_audience_study_answers_study ON audience_study_answers (study_id);
CREATE INDEX IF NOT EXISTS idx_audience_study_answers_persona ON audience_study_answers (persona_id);

-- The thread with one persona. study_id ties a follow-up question to the study
-- it is about (group_id is shared by one question asked to everyone); a plain
-- conversation has neither.
CREATE TABLE IF NOT EXISTS audience_messages (
    id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    persona_id UUID        NOT NULL REFERENCES audience_personas(id) ON DELETE CASCADE,
    study_id   UUID        REFERENCES audience_studies(id) ON DELETE CASCADE,
    group_id   UUID,
    role       TEXT        NOT NULL CHECK (role IN ('user', 'persona')),
    content    TEXT        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_audience_messages_persona ON audience_messages (persona_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audience_messages_study ON audience_messages (study_id, created_at) WHERE study_id IS NOT NULL;
